cd /tmp/bot-check && python3 - <<'E'
p='check.mjs'
s=open(p).read()
i=s.index('// DST day')
s=s[:i]+'''// DST day: Chicago springs forward 2026-03-08 08:00 UTC
assert.deepEqual(checkSms(mk(), at("2026-03-08T12:59:59Z")), r("quiet_hours")); // 07:59 CDT
assert.deepEqual(checkSms(mk(), at("2026-03-08T13:00:00Z")), ok); // 08:00 CDT
// Fall back 2026-11-01 07:00 UTC; 14:00Z = 08:00 CST
assert.deepEqual(checkSms(mk(), at("2026-11-01T13:59:59Z")), r("quiet_hours"));
assert.deepEqual(checkSms(mk(), at("2026-11-01T14:00:00Z")), ok);
const noon = at("2026-07-15T17:00:00Z");
const night = at("2026-07-16T05:00:00Z");
// opt-out / consent
assert.deepEqual(checkSms(mk({ optedOutAt: "2026-07-01T10:00:00Z" }), noon), r("opted_out"));
assert.deepEqual(checkSms(mk({ optedOutAt: "garbage" }), noon), r("opted_out"));
assert.deepEqual(checkSms(mk({ marketingConsent: false }), noon), r("no_marketing_consent"));
assert.deepEqual(checkSms(mk({ marketingConsent: "true" }), noon), r("no_marketing_consent"));
assert.deepEqual(checkSms(mk({ timeZone: "Mars/Base" }), noon), r("invalid_time_zone"));
assert.deepEqual(checkSms(mk({ timeZone: undefined }), noon), r("invalid_time_zone"));
assert.deepEqual(checkSms(mk({}, "Big sale today"), noon), r("missing_opt_out_instructions"));
assert.deepEqual(checkSms(mk({}, "Big sale. reply stop to end"), noon), ok);
assert.deepEqual(checkSms(mk({}, "Nonstop deals"), noon), r("missing_opt_out_instructions"));
// transactional: unaffected by consent, quiet hours, opt-out
assert.deepEqual(checkSms(tx({ marketingConsent: false }), night), ok);
assert.deepEqual(checkSms(tx({ optedOutAt: "2026-07-01T10:00:00Z", timeZone: "bad" }), night), ok);
// both kinds
for (const m of [mk, tx]) {
  assert.deepEqual(checkSms(m({ phone: "+442071838750" }), noon), r("invalid_phone"));
  assert.deepEqual(checkSms(m({ phone: "+11235550142" }), noon), r("invalid_phone"));
  assert.deepEqual(checkSms(m({ phone: "3125550142" }), noon), r("invalid_phone"));
  assert.deepEqual(checkSms(m({ phone: undefined }), noon), r("invalid_phone"));
}
assert.deepEqual(checkSms({ ...tx(), body: "  " }, noon), r("empty_body"));
assert.deepEqual(checkSms({ ...tx(), kind: "other" }, noon), r("invalid_message"));
assert.deepEqual(checkSms(null, noon), r("invalid_message"));
assert.deepEqual(checkSms({ kind: "marketing", body: "x" }, noon), r("invalid_message"));
assert.deepEqual(checkSms(tx(), new Date("x")), r("invalid_now"));
assert.deepEqual(checkSms(tx(), "2026-07-15"), r("invalid_now"));
console.log("all ok");
'''
open(p,'w').write(s)
E
for tz in UTC Asia/Tokyo America/Los_Angeles; do TZ=$tz node check.mjs; done
